1	//! Structure-of-Arrays batch storage for 3D Gaussian Splatting.
2	//!
3	//! # Layout
4	//!
5	//! Each field is a separate `Vec<f32>` (SoA) padded to `PREFERRED_F32_LANES`
6	//! so SIMD passes never hit a scalar tail. The batch holds:
7	//!
8	//! ```text
9	//!   12 scalar channels × capacity f32s  (mean xyz, scale xyz, quat wxyz, opacity)
10	//!   48 SH coefficients × capacity f32s  (degree-3 RGB: 3 × 16)
11	//! ```
12	//!
13	//! # SIMD covariance
14	//!
15	//! `covariance_x16(start, out)` batches 16 Σ = R · diag(s²) · Rᵀ computations
16	//! via `crate::simd::F32x16`, mirroring the scalar formula in
17	//! `Spd3::from_scale_quat` lane-by-lane. See that function for the
18	//! derivation of the rotation matrix and the Σ upper-triangle.
19	
20	use super::spd3::Spd3;
21	use crate::simd::{F32x16, PREFERRED_F32_LANES};
22	
23	// ════════════════════════════════════════════════════════════════════════════
24	// Constants
25	// ════════════════════════════════════════════════════════════════════════════
26	
27	/// SH degree (3 = 16 coefficients per RGB channel = 48 total per gaussian).
28	pub const SH_DEGREE: usize = 3;
29	/// 16 SH basis functions per channel for degree-3.
30	pub const SH_COEFFS_PER_CHANNEL: usize = (SH_DEGREE + 1) * (SH_DEGREE + 1);
31	/// 48 floats per gaussian total (3 channels × 16 coeffs).
32	pub const SH_COEFFS_PER_GAUSSIAN: usize = SH_COEFFS_PER_CHANNEL * 3;
33	
34	// ════════════════════════════════════════════════════════════════════════════
35	// Padding helper (self-contained — pad_to_lanes in renderer.rs is not pub)
36	// ════════════════════════════════════════════════════════════════════════════
37	
38	/// Round `n` up to the nearest multiple of `lanes`.
39	#[inline]
40	const fn pad_to_lanes(n: usize, lanes: usize) -> usize {
41	    (n + lanes - 1) / lanes * lanes
42	}
43	
44	// ════════════════════════════════════════════════════════════════════════════
45	// Gaussian3D — convenience AoS input shape
46	// ════════════════════════════════════════════════════════════════════════════
47	
48	/// Single 3D gaussian — the test/demo input shape. Not used in the hot path;
49	/// the rasterizer reads from `GaussianBatch` directly.
50	pub struct Gaussian3D {
51	    /// World-space mean position [x, y, z].
52	    pub mean: [f32; 3],
53	    /// Anisotropic scale standard deviations [sx, sy, sz].
54	    pub scale: [f32; 3],
55	    /// Unit quaternion [w, x, y, z].
56	    pub quat: [f32; 4],
57	    /// Opacity in [0, 1].
58	    pub opacity: f32,
59	    /// Degree-3 SH coefficients (48 floats). Layout:
60	    /// `sh[ch * 16 + basis_idx]` for ch in 0..3.
61	    pub sh: [f32; SH_COEFFS_PER_GAUSSIAN],
62	}
63	
64	impl Gaussian3D {
65	    /// Identity-rotation gaussian at the origin, isotropic unit scale,
66	    /// fully opaque, SH coefficients all zero. Useful as a test stub
67	    /// before `push`.
68	    pub fn unit() -> Self {
69	        Self {
70	            mean: [0.0, 0.0, 0.0],
71	            scale: [1.0, 1.0, 1.0],
72	            quat: [1.0, 0.0, 0.0, 0.0],
73	            opacity: 1.0,
74	            sh: [0.0; SH_COEFFS_PER_GAUSSIAN],
75	        }
76	    }
77	}
78	
79	// ════════════════════════════════════════════════════════════════════════════
80	// GaussianBatch — SoA storage
81	// ════════════════════════════════════════════════════════════════════════════
82	
83	/// Structure-of-Arrays batch of 3D gaussians, padded to `PREFERRED_F32_LANES`
84	/// so SIMD passes never encounter a scalar tail.
85	///
86	/// Mirror of `hpc::renderer::RenderFrame` but for gaussian splat fields.
87	pub struct GaussianBatch {
88	    /// Active gaussian count (≤ capacity).
89	    pub len: usize,
90	    /// Padded capacity (multiple of PREFERRED_F32_LANES).
91	    pub capacity: usize,
92	    /// Position (length = capacity each).
93	    pub mean_x: Vec<f32>,
94	    pub mean_y: Vec<f32>,
95	    pub mean_z: Vec<f32>,
96	    /// Anisotropic standard-deviation scale (length = capacity each).
97	    pub scale_x: Vec<f32>,
98	    pub scale_y: Vec<f32>,
99	    pub scale_z: Vec<f32>,
100	    /// Rotation quaternion (w, x, y, z), unit norm (length = capacity each).
101	    pub quat_w: Vec<f32>,
102	    pub quat_x: Vec<f32>,
103	    pub quat_y: Vec<f32>,
104	    pub quat_z: Vec<f32>,
105	    /// Opacity in [0, 1] (length = capacity).
106	    pub opacity: Vec<f32>,
107	    /// SH coefficients (length = SH_COEFFS_PER_GAUSSIAN * capacity).
108	    /// Layout: gaussian-major, channel-major within:
109	    ///   sh[i * 48 + ch * 16 + basis_idx]
110	    pub sh: Vec<f32>,
111	}
112	
113	impl GaussianBatch {
114	    /// Allocate empty batch with capacity for `n` gaussians (rounded up
115	    /// to PREFERRED_F32_LANES). All buffers zero-initialized.
116	    pub fn with_capacity(n: usize) -> Self {
117	        let capacity = pad_to_lanes(n.max(1), PREFERRED_F32_LANES);
118	        Self {
119	            len: 0,
120	            capacity,
121	            mean_x: vec![0.0; capacity],
122	            mean_y: vec![0.0; capacity],
123	            mean_z: vec![0.0; capacity],
124	            scale_x: vec![0.0; capacity],
125	            scale_y: vec![0.0; capacity],
126	            scale_z: vec![0.0; capacity],
127	            quat_w: vec![0.0; capacity],
128	            quat_x: vec![0.0; capacity],
129	            quat_y: vec![0.0; capacity],
130	            quat_z: vec![0.0; capacity],
131	            opacity: vec![0.0; capacity],
132	            sh: vec![0.0; SH_COEFFS_PER_GAUSSIAN * capacity],
133	        }
134	    }
135	
136	    /// Reset to empty (`len = 0`) without deallocating. Trailing slots
137	    /// already zero from `with_capacity`; new pushes overwrite.
138	    pub fn clear(&mut self) {
139	        self.len = 0;
140	    }
141	
142	    /// Push one gaussian into the next slot. Panics if `len == capacity`.
143	    /// Callers in tight loops should use `with_capacity` to pre-size.
144	    pub fn push(&mut self, g: Gaussian3D) {
145	        assert!(self.len < self.capacity, "GaussianBatch::push: len == capacity ({})", self.capacity);
146	        let i = self.len;
147	        self.mean_x[i] = g.mean[0];
148	        self.mean_y[i] = g.mean[1];
149	        self.mean_z[i] = g.mean[2];
150	        self.scale_x[i] = g.scale[0];
151	        self.scale_y[i] = g.scale[1];
152	        self.scale_z[i] = g.scale[2];
153	        self.quat_w[i] = g.quat[0];
154	        self.quat_x[i] = g.quat[1];
155	        self.quat_y[i] = g.quat[2];
156	        self.quat_z[i] = g.quat[3];
157	        self.opacity[i] = g.opacity;
158	        let sh_base = i * SH_COEFFS_PER_GAUSSIAN;
159	        self.sh[sh_base..sh_base + SH_COEFFS_PER_GAUSSIAN].copy_from_slice(&g.sh);
160	        self.len += 1;
161	    }
162	
163	    /// Reconstruct the i-th gaussian's covariance from scale + quat via
164	    /// `Spd3::from_scale_quat`. Panics if `i >= len`.
165	    pub fn covariance(&self, i: usize) -> Spd3 {
166	        assert!(i < self.len, "covariance: index {i} >= len {}", self.len);
167	        let scale = [self.scale_x[i], self.scale_y[i], self.scale_z[i]];
168	        let quat = [self.quat_w[i], self.quat_x[i], self.quat_y[i], self.quat_z[i]];
169	        Spd3::from_scale_quat(scale, quat)
170	    }
171	
172	    /// Batched covariance reconstruction: 16 gaussians at indices
173	    /// `[start, start + 16)`. Writes into `out`. Panics if
174	    /// `start + 16 > self.capacity`.
175	    ///
176	    /// Uses `crate::simd::F32x16` to SIMD-batch the quat→rotation
177	    /// cross products and the Σ = R · diag(s²) · Rᵀ product.
178	    /// Output is AoS `[Spd3; 16]`.
179	    ///
180	    /// # Precondition on padded lanes
181	    ///
182	    /// The bound is on `capacity`, NOT `len`, so the SIMD pad allows
183	    /// any 16-aligned block read at the cost of correctness for slots
184	    /// `>= len`. Padded slots have `scale = [0, 0, 0]` and
185	    /// `quat = [0, 0, 0, 0]` (degenerate zero-norm quaternion), which
186	    /// the closed-form Σ = R · diag(s²) · Rᵀ collapses to the zero
187	    /// matrix — **non-SPD** and unsafe to feed into a downstream
188	    /// inverse / sandwich. Callers walking the batch in 16-wide
189	    /// chunks (e.g. PR 3's `project_batch`) must mask the trailing
190	    /// `(capacity - len)` lanes of the final chunk before consuming
191	    /// `out`. The `valid` mask carried by `ProjectedBatch` (PR 3) is
192	    /// the canonical place for that bookkeeping.
193	    pub fn covariance_x16(&self, start: usize, out: &mut [Spd3; 16]) {
194	        assert!(start + 16 <= self.capacity, "covariance_x16: start ({start}) + 16 > capacity ({})", self.capacity);
195	
196	        // ── 1. Load 7 SoA channels into F32x16 lanes ────────────────────
197	        let qw = F32x16::from_slice(&self.quat_w[start..start + 16]);
198	        let qx = F32x16::from_slice(&self.quat_x[start..start + 16]);
199	        let qy = F32x16::from_slice(&self.quat_y[start..start + 16]);
200	        let qz = F32x16::from_slice(&self.quat_z[start..start + 16]);
201	        let sx = F32x16::from_slice(&self.scale_x[start..start + 16]);
202	        let sy = F32x16::from_slice(&self.scale_y[start..start + 16]);
203	        let sz = F32x16::from_slice(&self.scale_z[start..start + 16]);
204	
205	        // ── 2. Intermediate quaternion products (mirror from_scale_quat) ─
206	        let two = F32x16::splat(2.0);
207	        let one = F32x16::splat(1.0);
208	
209	        let xx = qx * qx;
210	        let yy = qy * qy;
211	        let zz = qz * qz;
212	        let xy = qx * qy;
213	        let xz = qx * qz;
214	        let yz = qy * qz;
215	        let wx = qw * qx;
216	        let wy = qw * qy;
217	        let wz = qw * qz;
218	
219	        // Rotation matrix (row-major):
220	        //   R = [[r00, r01, r02],
221	        //        [r10, r11, r12],
222	        //        [r20, r21, r22]]
223	        let r00 = one - two * (yy + zz);
224	        let r01 = two * (xy - wz);
225	        let r02 = two * (xz + wy);
226	        let r10 = two * (xy + wz);
227	        let r11 = one - two * (xx + zz);
228	        let r12 = two * (yz - wx);
229	        let r20 = two * (xz - wy);
230	        let r21 = two * (yz + wx);
231	        let r22 = one - two * (xx + yy);
232	
233	        // ── 3. s² = scale squared ────────────────────────────────────────
234	        let s0 = sx * sx;
235	        let s1 = sy * sy;
236	        let s2 = sz * sz;
237	
238	        // ── 4. M = R · diag(s²): scale column k by sₖ² ─────────────────
239	        let m00 = r00 * s0;
240	        let m01 = r01 * s1;
241	        let m02 = r02 * s2;
242	        let m10 = r10 * s0;
243	        let m11 = r11 * s1;
244	        let m12 = r12 * s2;
245	        let m20 = r20 * s0;
246	        let m21 = r21 * s1;
247	        let m22 = r22 * s2;
248	
249	        // ── 5. Σ = M · Rᵀ — upper triangle ──────────────────────────────
250	        let a11 = m00 * r00 + m01 * r01 + m02 * r02;
251	        let a12 = m00 * r10 + m01 * r11 + m02 * r12;
252	        let a13 = m00 * r20 + m01 * r21 + m02 * r22;
253	        let a22 = m10 * r10 + m11 * r11 + m12 * r12;
254	        let a23 = m10 * r20 + m11 * r21 + m12 * r22;
255	        let a33 = m20 * r20 + m21 * r21 + m22 * r22;
256	
257	        // ── 6. Scatter SoA → AoS [Spd3; 16] ────────────────────────────
258	        let mut buf_a11 = [0.0f32; 16];
259	        let mut buf_a12 = [0.0f32; 16];
260	        let mut buf_a13 = [0.0f32; 16];
261	        let mut buf_a22 = [0.0f32; 16];
262	        let mut buf_a23 = [0.0f32; 16];
263	        let mut buf_a33 = [0.0f32; 16];
264	        a11.copy_to_slice(&mut buf_a11);
265	        a12.copy_to_slice(&mut buf_a12);
266	        a13.copy_to_slice(&mut buf_a13);
267	        a22.copy_to_slice(&mut buf_a22);
268	        a23.copy_to_slice(&mut buf_a23);
269	        a33.copy_to_slice(&mut buf_a33);
270	        for k in 0..16 {
271	            out[k] = Spd3::new(buf_a11[k], buf_a12[k], buf_a13[k], buf_a22[k], buf_a23[k], buf_a33[k]);
272	        }
273	    }
274	}
