276	// ════════════════════════════════════════════════════════════════════════════
277	// Tests
278	// ════════════════════════════════════════════════════════════════════════════
279	
280	#[cfg(test)]
281	mod tests {
282	    use super::*;
283	
284	    fn approx(a: f32, b: f32, tol: f32) -> bool {
285	        (a - b).abs() <= tol
286	    }
287	
288	    fn approx_spd3(a: Spd3, b: Spd3, tol: f32) -> bool {
289	        approx(a.a11, b.a11, tol)
290	            && approx(a.a12, b.a12, tol)
291	            && approx(a.a13, b.a13, tol)
292	            && approx(a.a22, b.a22, tol)
293	            && approx(a.a23, b.a23, tol)
294	            && approx(a.a33, b.a33, tol)
295	    }
296	
297	    // Deterministic xorshift32.
298	    fn rng_u32(state: &mut u32) -> u32 {
299	        *state ^= *state << 13;
300	        *state ^= *state >> 17;
301	        *state ^= *state << 5;
302	        *state
303	    }
304	
305	    fn rng_f32(state: &mut u32) -> f32 {
306	        rng_u32(state) as f32 / u32::MAX as f32
307	    }
308	
309	    /// Build a normalized quaternion from 4 random floats.
310	    fn rng_quat(state: &mut u32) -> [f32; 4] {
311	        let mut q = [
312	            -1.0 + 2.0 * rng_f32(state),
313	            -1.0 + 2.0 * rng_f32(state),
314	            -1.0 + 2.0 * rng_f32(state),
315	            -1.0 + 2.0 * rng_f32(state),
316	        ];
317	        let n = (q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3]).sqrt();
318	        for v in &mut q {
319	            *v /= n;
320	        }
321	        q
322	    }
323	
324	    fn rng_scale(state: &mut u32) -> [f32; 3] {
325	        [0.2 + 1.8 * rng_f32(state), 0.2 + 1.8 * rng_f32(state), 0.2 + 1.8 * rng_f32(state)]
326	    }
327	
328	    // ── Test 1 ──────────────────────────────────────────────────────────────
329	
330	    #[test]
331	    fn gaussian_batch_with_capacity_pads_lanes() {
332	        for n in [1usize, 7, 15, 16, 17, 100] {
333	            let b = GaussianBatch::with_capacity(n);
334	            let expected = pad_to_lanes(n.max(1), PREFERRED_F32_LANES);
335	            assert_eq!(b.capacity, expected, "n={n}: capacity mismatch");
336	            assert_eq!(b.len, 0);
337	            assert_eq!(b.mean_x.len(), expected, "n={n}: mean_x len");
338	            assert_eq!(b.mean_y.len(), expected, "n={n}: mean_y len");
339	            assert_eq!(b.mean_z.len(), expected, "n={n}: mean_z len");
340	            assert_eq!(b.scale_x.len(), expected, "n={n}: scale_x len");
341	            assert_eq!(b.scale_y.len(), expected, "n={n}: scale_y len");
342	            assert_eq!(b.scale_z.len(), expected, "n={n}: scale_z len");
343	            assert_eq!(b.quat_w.len(), expected, "n={n}: quat_w len");
344	            assert_eq!(b.quat_x.len(), expected, "n={n}: quat_x len");
345	            assert_eq!(b.quat_y.len(), expected, "n={n}: quat_y len");
346	            assert_eq!(b.quat_z.len(), expected, "n={n}: quat_z len");
347	            assert_eq!(b.opacity.len(), expected, "n={n}: opacity len");
348	            assert_eq!(b.sh.len(), SH_COEFFS_PER_GAUSSIAN * expected, "n={n}: sh len");
349	        }
350	    }
351	
352	    // ── Test 2 ──────────────────────────────────────────────────────────────
353	
354	    #[test]
355	    fn gaussian_batch_push_preserves_alignment() {
356	        let n = 4;
357	        let mut b = GaussianBatch::with_capacity(n);
358	        let cap = b.capacity;
359	        for i in 0..n {
360	            let mut g = Gaussian3D::unit();
361	            g.mean[0] = i as f32 + 1.0;
362	            g.opacity = (i as f32 + 1.0) * 0.1;
363	            b.push(g);
364	        }
365	        assert_eq!(b.len, n);
366	        // All pushed slots populated.
367	        for i in 0..n {
368	            assert!(b.mean_x[i] != 0.0, "slot {i} mean_x should be non-zero");
369	            assert!(b.opacity[i] != 0.0, "slot {i} opacity should be non-zero");
370	        }
371	        // Slots after len still zero (padding).
372	        for i in n..cap {
373	            assert_eq!(b.mean_x[i], 0.0, "pad slot {i} mean_x not zero");
374	            assert_eq!(b.opacity[i], 0.0, "pad slot {i} opacity not zero");
375	        }
376	    }
377	
378	    // ── Test 3 ──────────────────────────────────────────────────────────────
379	
380	    #[test]
381	    #[should_panic]
382	    fn gaussian_batch_push_panics_at_capacity() {
383	        let mut b = GaussianBatch::with_capacity(1);
384	        // Fill to capacity.
385	        for _ in 0..b.capacity {
386	            b.push(Gaussian3D::unit());
387	        }
388	        // This push must panic.
389	        b.push(Gaussian3D::unit());
390	    }
391	
392	    // ── Test 4 ──────────────────────────────────────────────────────────────
393	
394	    #[test]
395	    fn covariance_from_unit_quat_is_diag_of_scale_squared() {
396	        let mut b = GaussianBatch::with_capacity(1);
397	        let mut g = Gaussian3D::unit();
398	        g.scale = [2.0, 1.5, 0.8];
399	        g.quat = [1.0, 0.0, 0.0, 0.0]; // identity rotation
400	        b.push(g);
401	        let cov = b.covariance(0);
402	        // Σ = diag(s²) = diag(4.0, 2.25, 0.64)
403	        assert!(approx(cov.a11, 4.0, 1e-6), "a11={}", cov.a11);
404	        assert!(approx(cov.a22, 2.25, 1e-6), "a22={}", cov.a22);
405	        assert!(approx(cov.a33, 0.64, 1e-6), "a33={}", cov.a33);
406	        assert!(approx(cov.a12, 0.0, 1e-6), "a12={}", cov.a12);
407	        assert!(approx(cov.a13, 0.0, 1e-6), "a13={}", cov.a13);
408	        assert!(approx(cov.a23, 0.0, 1e-6), "a23={}", cov.a23);
409	    }
410	
411	    // ── Test 5 ──────────────────────────────────────────────────────────────
412	
413	    #[test]
414	    fn covariance_with_90deg_y_rotation_matches_spd3() {
415	        // 90° about Y: quat = (cos 45°, 0, sin 45°, 0)
416	        let h = (0.5f32).sqrt();
417	        let scale = [2.0f32, 1.5, 0.8];
418	        let quat = [h, 0.0, h, 0.0];
419	        let mut b = GaussianBatch::with_capacity(1);
420	        let mut g = Gaussian3D::unit();
421	        g.scale = scale;
422	        g.quat = quat;
423	        b.push(g);
424	        let got = b.covariance(0);
425	        let expected = Spd3::from_scale_quat(scale, quat);
426	        assert!(approx_spd3(got, expected, 1e-5), "got={got:?} expected={expected:?}");
427	    }
428	
429	    // ── Test 6 ──────────────────────────────────────────────────────────────
430	
431	    #[test]
432	    fn covariance_x16_matches_scalar_loop() {
433	        let mut state = 0xC0FFEE_u32;
434	        let mut b = GaussianBatch::with_capacity(16);
435	        for _ in 0..16 {
436	            let mut g = Gaussian3D::unit();
437	            g.scale = rng_scale(&mut state);
438	            g.quat = rng_quat(&mut state);
439	            b.push(g);
440	        }
441	        let mut simd_out = [Spd3::ZERO; 16];
442	        b.covariance_x16(0, &mut simd_out);
443	        for i in 0..16 {
444	            let scalar = b.covariance(i);
445	            assert!(approx_spd3(simd_out[i], scalar, 1e-4), "lane {i}: simd={:?} scalar={:?}", simd_out[i], scalar,);
446	        }
447	    }
448	
449	    // ── Test 7 ──────────────────────────────────────────────────────────────
450	
451	    #[test]
452	    fn clear_resets_len_preserves_capacity() {
453	        let mut b = GaussianBatch::with_capacity(8);
454	        let cap = b.capacity;
455	        for _ in 0..4 {
456	            b.push(Gaussian3D::unit());
457	        }
458	        assert_eq!(b.len, 4);
459	        b.clear();
460	        assert_eq!(b.len, 0);
461	        assert_eq!(b.capacity, cap);
462	    }
