464	    // ── Test 8 ──────────────────────────────────────────────────────────────
465	
466	    #[test]
467	    fn gaussian3d_unit_constructor() {
468	        let g = Gaussian3D::unit();
469	        assert_eq!(g.mean, [0.0, 0.0, 0.0]);
470	        assert_eq!(g.scale, [1.0, 1.0, 1.0]);
471	        assert_eq!(g.quat, [1.0, 0.0, 0.0, 0.0]);
472	        assert_eq!(g.opacity, 1.0);
473	        assert_eq!(g.sh, [0.0; SH_COEFFS_PER_GAUSSIAN]);
474	    }
