476	    // ── Test 9 — covariance_x16 with start > 0 (PP-13 PR2 P1 promoted) ─────
477	    //
478	    // The existing covariance_x16_matches_scalar_loop test fires with
479	    // start=0. An off-by-one in the SoA slice arithmetic
480	    // (`self.quat_w[start..start+16]`) would still pass start=0 since
481	    // any constant offset of 0 collapses to identity. Walk a non-zero
482	    // start so each input index `start + k` differs from lane index `k`.
483	    #[test]
484	    fn covariance_x16_with_nonzero_start_matches_scalar() {
485	        let mut state = 0xACE0_C0DEu32;
486	        let mut batch = GaussianBatch::with_capacity(48);
487	        for _ in 0..32 {
488	            batch.push(sample_gaussian3d(&mut state));
489	        }
490	        let start = 16; // walk past the first SIMD block
491	        let mut out_simd = [Spd3::ZERO; 16];
492	        batch.covariance_x16(start, &mut out_simd);
493	        for k in 0..16 {
494	            let scalar = batch.covariance(start + k);
495	            // 1e-4 absolute matches PR 1's sandwich_x16 tolerance; the
496	            // SoA-transpose-then-recombine pipeline accumulates the
497	            // same evaluation-order noise.
498	            assert!(
499	                approx_spd3(out_simd[k], scalar, 1e-4),
500	                "lane k={k} (index {}): simd={:?}, scalar={:?}",
501	                start + k,
502	                out_simd[k],
503	                scalar,
504	            );
505	        }
506	    }
507	
508	    // ── Test 10 — SH round-trip through SoA (PP-13 PR2 P1 promoted) ─────────
509	    //
510	    // Verifies the bridge between `push` (writes the 48-float SH block
511	    // at `self.sh[i*48..]`) and `sh::sh_eval_deg3` (reads at the same
512	    // offset). If `SH_COEFFS_PER_GAUSSIAN` were misdefined, or `push`'s
513	    // SH copy used the wrong base, the resulting RGB would silently
514	    // drift from the analytical expectation. Uses Test 8 from sh.rs's
515	    // suite as the analytical reference (basis k=0 → SH_C0 + 0.5).
516	    #[test]
517	    fn push_then_sh_eval_round_trips_through_soa() {
518	        use super::super::sh::sh_eval_deg3;
519	        let mut g = Gaussian3D::unit();
520	        // Non-zero SH coefficient for channel R, basis k=0 (Y_00 — the
521	        // direction-invariant DC term). Channels G/B all-zero → 0.5.
522	        g.sh[0] = 1.0;
523	        // Also set a coefficient at the LAST slot to verify the full
524	        // 48-float span survives the SoA copy.
525	        g.sh[47] = 0.5;
526	        let mut batch = GaussianBatch::with_capacity(16);
527	        // Push 5 unit gaussians first, then ours at index 5, so the SoA
528	        // offset arithmetic isn't trivial.
529	        for _ in 0..5 {
530	            batch.push(Gaussian3D::unit());
531	        }
532	        batch.push(g);
533	        // Pull the SH slice for gaussian 5 directly out of the batch and
534	        // run sh_eval at d=(0,0,1) (where Y_00 dominates).
535	        let base = 5 * SH_COEFFS_PER_GAUSSIAN;
536	        let sh_slice = &batch.sh[base..base + SH_COEFFS_PER_GAUSSIAN];
537	        // Sanity-check the SoA contents: indices 0 and 47 survived; the
538	        // 46 in between are zero (this is also a fence-post check on
539	        // the push SH-copy bounds).
540	        assert!((sh_slice[0] - 1.0).abs() < 1e-7, "SoA sh[0] for gaussian 5 = {}, expected 1.0", sh_slice[0]);
541	        assert!((sh_slice[47] - 0.5).abs() < 1e-7, "SoA sh[47] for gaussian 5 = {}, expected 0.5", sh_slice[47]);
542	        for k in 1..47 {
543	            assert!(sh_slice[k].abs() < 1e-7, "SoA sh[{k}] for gaussian 5 = {}, expected 0", sh_slice[k]);
544	        }
545	        // And the round-trip evaluation must reflect that DC coefficient.
546	        let rgb = sh_eval_deg3(sh_slice, [0.0, 0.0, 1.0]);
547	        // sh.rs SH_C0 ≈ 0.282; with the +0.5 Inria offset → 0.782.
548	        assert!(
549	            (rgb[0] - 0.7820948).abs() < 1e-5,
550	            "R channel via SoA: got {}, want ≈ {} (SH_C0 + 0.5)",
551	            rgb[0],
552	            0.7820948
553	        );
554	        // G channel = 0.5 (all-zero coeffs).
555	        // B channel: sh[47] = 0.5 is the *last* B coefficient (basis k=15
556	        // = Y_3,3 = -SH_C3[6] · x(x²-3y²)). At d=(0,0,1) x=0 so this
557	        // basis vanishes → B = 0.5.
558	        assert!((rgb[1] - 0.5).abs() < 1e-6, "G channel: got {}, want 0.5", rgb[1]);
559	        assert!(
560	            (rgb[2] - 0.5).abs() < 1e-6,
561	            "B channel (sh[47] basis vanishes at d=(0,0,1)): got {}, want 0.5",
562	            rgb[2]
563	        );
564	    }
565	
566	    // ── Helpers ─────────────────────────────────────────────────────────────
567	
568	    /// Build a random Gaussian3D — reuses Worker C's existing `rng_*`
569	    /// helpers so the test module stays single-sourced.
570	    fn sample_gaussian3d(state: &mut u32) -> Gaussian3D {
571	        Gaussian3D {
572	            mean: [rng_f32(state), rng_f32(state), rng_f32(state)],
573	            scale: rng_scale(state),
574	            quat: rng_quat(state),
575	            opacity: rng_f32(state),
576	            sh: [0.0; SH_COEFFS_PER_GAUSSIAN],
577	        }
578	    }
