1	//! Criterion benches for `ndarray::hpc::splat3d` kernels.
2	//!
3	//! Per-PR bench growth:
4	//! - PR 1: `spd3::sandwich` scalar vs `sandwich_x16` SIMD (target ≥10×
5	//!   on AVX-512), `Spd3::eig` Smith-1961 closed-form throughput,
6	//!   `Spd3::from_scale_quat` (the 3DGS canonical builder).
7	//! - PR 2: `gaussian::GaussianBatch::covariance_x16`, `sh::sh_eval_deg3_x16`.
8	//! - PR 3+: `project_batch`, tile binning, per-tile rasterize.
9	//!
10	//! Hardware specs and absolute timings live in `benches/RESULTS.md`,
11	//! updated per-PR. The bench output committed to RESULTS.md is the
12	//! gate against regression — a >5% slowdown on any kernel blocks
13	//! merge per the sprint discipline.
14	
15	use criterion::{black_box, criterion_group, criterion_main, Criterion};
16	use ndarray::hpc::splat3d::{sandwich, sandwich_x16, Spd3};
17	
18	/// Deterministic 16 distinct SPD pairs. Using `[m; 16]` (PP-13 P0.2
19	/// finding) let the optimizer constant-fold the scalar loop to one
20	/// `sandwich` + ×16, which would make the SIMD-vs-scalar bench measure
21	/// loop-folding rather than real SIMD parallelism. Each lane gets its
22	/// own scale/quat so the inputs differ entry-wise across all 6 SoA
23	/// channels the SIMD kernel transposes.
24	fn build_distinct_pairs() -> ([Spd3; 16], [Spd3; 16]) {
25	    let mut ms = [Spd3::I; 16];
26	    let mut ns = [Spd3::I; 16];
27	    for k in 0..16 {
28	        let t = (k as f32 + 1.0) * 0.0625;
29	        let scale_m = [0.5 + 1.0 * t, 0.4 + 0.9 * t, 0.3 + 1.2 * t];
30	        let scale_n = [1.3 - 0.7 * t, 0.8 + 0.5 * t, 1.1 - 0.4 * t];
31	        // Two different axis families — half rotate about Y, half about X+Z
32	        // diagonal — so the rotation matrices populate different sets of
33	        // off-diagonal cross terms.
34	        let theta_m = 0.2 + 0.4 * t;
35	        let theta_n = 0.7 - 0.3 * t;
36	        let quat_m = [theta_m.cos(), 0.0, theta_m.sin(), 0.0];
37	        let sqh = (0.5f32).sqrt();
38	        let quat_n = [theta_n.cos(), theta_n.sin() * sqh, 0.0, theta_n.sin() * sqh];
39	        ms[k] = Spd3::from_scale_quat(scale_m, quat_m);
40	        ns[k] = Spd3::from_scale_quat(scale_n, quat_n);
41	    }
42	    (ms, ns)
43	}
44	
45	fn bench_spd3_sandwich_scalar_loop(c: &mut Criterion) {
46	    let (ms, ns) = build_distinct_pairs();
47	
48	    c.bench_function("spd3_sandwich_scalar_x16_loop", |b| {
49	        b.iter(|| {
50	            let mut acc = Spd3::ZERO;
51	            for i in 0..16 {
52	                let r = sandwich(black_box(&ms[i]), black_box(&ns[i]));
53	                acc.a11 += r.a11;
54	                acc.a22 += r.a22;
55	                acc.a33 += r.a33;
56	                acc.a12 += r.a12;
57	                acc.a13 += r.a13;
58	                acc.a23 += r.a23;
59	            }
60	            black_box(acc);
61	        });
62	    });
63	}
64	
65	fn bench_spd3_sandwich_simd_x16(c: &mut Criterion) {
66	    let (ms, ns) = build_distinct_pairs();
67	    let mut out = [Spd3::ZERO; 16];
68	
69	    c.bench_function("spd3_sandwich_simd_x16", |b| {
70	        b.iter(|| {
71	            sandwich_x16(black_box(&ms), black_box(&ns), &mut out);
72	            black_box(&out);
73	        });
74	    });
75	}
76	
77	fn bench_spd3_eig(c: &mut Criterion) {
78	    let s = Spd3::from_scale_quat([2.0, 1.5, 0.8], [0.8660254, 0.5, 0.0, 0.0]);
79	    c.bench_function("spd3_eig_smith_1961", |b| {
80	        b.iter(|| {
81	            let r = black_box(&s).eig();
82	            black_box(r);
83	        });
84	    });
85	}
86	
87	fn bench_spd3_from_scale_quat(c: &mut Criterion) {
88	    let scale = [1.3f32, 0.9, 0.6];
89	    let quat = [0.7071068f32, 0.0, 0.7071068, 0.0];
90	    c.bench_function("spd3_from_scale_quat", |b| {
91	        b.iter(|| {
92	            let s = Spd3::from_scale_quat(black_box(scale), black_box(quat));
93	            black_box(s);
94	        });
95	    });
96	}
97	
98	criterion_group!(
99	    spd3, bench_spd3_sandwich_scalar_loop, bench_spd3_sandwich_simd_x16, bench_spd3_eig, bench_spd3_from_scale_quat,
100	);
101	criterion_main!(spd3);
