2	//!
3	//! Builds a synthetic 1000-gaussian scene with known structure,
4	//! runs it through `SplatRenderer::tick`, and validates the
5	//! framebuffer against analytical expectations. This is the e2e
6	//! regression guard the sprint's "Definition of done" calls out
7	//! ("renders a scene end-to-end on CPU"). The bicycle-scene SSIM
8	//! comparison vs reference CUDA render is left for a follow-up
9	//! session when the .ply asset is mirrored locally.
10	//!
11	//! ```bash
12	//! cargo test --features splat3d --test splat3d_correctness
13	//! ```
14	
15	#![cfg(feature = "splat3d")]
16	
17	use ndarray::hpc::splat3d::{Camera, Gaussian3D, SplatFrame, SplatRenderer, SH_COEFFS_PER_GAUSSIAN};
18	
19	/// Build a deterministic 1000-gaussian scene laid out as a 10×10×10
20	/// cubic grid spanning world coordinates `[-2, 2]³`. Each gaussian:
21	/// - Position: cube vertex `(x, y, z)` with `x, y, z ∈ {-2, -1.5, …, 2}`.
22	/// - Scale: isotropic 0.08 (small enough that gaussians don't overlap).
23	/// - Quat: identity (no rotation).
24	/// - Opacity: 0.9.
25	/// - Color (via SH DC term): `((x + 2) / 4, (y + 2) / 4, (z + 2) / 4)` —
26	///   one color channel per axis, so the cube renders a smooth RGB
27	///   gradient depending on which face the camera looks at.
28	fn build_synthetic_cube_scene(frame: &mut SplatFrame) {
29	    let n = 10;
30	    let mut state = 0xC0FFEEu32;
31	    let mut xor_advance = |s: &mut u32| {
32	        *s ^= *s << 13;
33	        *s ^= *s >> 17;
34	        *s ^= *s << 5;
35	    };
36	
37	    for ix in 0..n {
38	        for iy in 0..n {
39	            for iz in 0..n {
40	                let x = -2.0 + (ix as f32) * (4.0 / (n - 1) as f32);
41	                let y = -2.0 + (iy as f32) * (4.0 / (n - 1) as f32);
42	                let z = -2.0 + (iz as f32) * (4.0 / (n - 1) as f32);
43	                let mut sh = [0.0f32; SH_COEFFS_PER_GAUSSIAN];
44	                // DC term per channel (sh[ch * 16 + 0]):
45	                //   R = ix/(n-1), G = iy/(n-1), B = iz/(n-1)
46	                //   Pre-divide by SH_C0 ≈ 0.282 so the output (which is
47	                //   SH_C0 · sh[0] + 0.5) lands at the intended color.
48	                let sh_c0: f32 = 0.28209479177387814;
49	                sh[0] = (ix as f32) / (n - 1) as f32 / sh_c0;
50	                sh[16] = (iy as f32) / (n - 1) as f32 / sh_c0;
51	                sh[32] = (iz as f32) / (n - 1) as f32 / sh_c0;
52	                // Add a tiny jitter to the SH coefficients beyond the DC
53	                // term so the eval path exercises the higher-degree
54	                // basis functions (regression for PR 2's SH math).
55	                xor_advance(&mut state);
56	                sh[1] = (state as f32 / u32::MAX as f32 - 0.5) * 0.05;
57	                frame.gaussians.push(Gaussian3D {
58	                    mean: [x, y, z],
59	                    scale: [0.08, 0.08, 0.08],
60	                    quat: [1.0, 0.0, 0.0, 0.0],
61	                    opacity: 0.9,
62	                    sh,
63	                });
64	            }
65	        }
66	    }
67	}
