69	/// A simple "camera at (cx, cy, cz) looking down its own +Z axis with
70	/// no rotation" view matrix. Used for the smoke-test renders so the
71	/// gaussian arrangement projects predictably to screen space.
72	fn camera_looking_down_z(cx: f32, cy: f32, cz: f32, width: u32, height: u32) -> Camera {
73	    // World-to-camera translation: subtract camera position from world
74	    // coordinates. View matrix is identity rotation + (-cx, -cy, -cz)
75	    // translation. So a world point at (cx + dx, cy + dy, cz + dz)
76	    // ends up at camera-frame (dx, dy, dz).
77	    let view = [[1.0, 0.0, 0.0, -cx], [0.0, 1.0, 0.0, -cy], [0.0, 0.0, 1.0, -cz], [0.0, 0.0, 0.0, 1.0]];
78	    let fx = (width.max(height)) as f32;
79	    Camera {
80	        view,
81	        fx,
82	        fy: fx,
83	        cx: (width as f32) * 0.5,
84	        cy: (height as f32) * 0.5,
85	        near: 0.01,
86	        far: 1000.0,
87	        width,
88	        height,
89	        position: [cx, cy, cz],
90	    }
91	}
