98	fn end_to_end_synthetic_cube_renders_without_panic() {
99	    // 1000-gaussian scene, 256×256 image, camera placed at (0, 0, -5)
100	    // so the cube sits at depth ~3-7 in camera space and projects to
101	    // the image. Renders one frame; asserts the framebuffer has
102	    // non-trivial pixel variance (i.e. SOMETHING was rendered, not
103	    // just a flat background).
104	    let mut frame = SplatFrame::with_capacity(1000, 256, 256);
105	    build_synthetic_cube_scene(&mut frame);
106	    assert_eq!(frame.gaussians.len, 1000);
107	
