109	    frame.tick(&camera, [0.0, 0.0, 0.0]);
110	
111	    assert_eq!(frame.frame_id, 1);
112	    assert_eq!(frame.framebuffer.len(), 256 * 256 * 3);
113	
114	    // Pixel variance test: at least 1% of pixels must differ from the
115	    // pure-background value (= 0.0). Otherwise the rasterizer wrote
116	    // nothing.
117	    let lit_pixels = frame
118	        .framebuffer
119	        .chunks_exact(3)
120	        .filter(|p| p[0] > 0.01 || p[1] > 0.01 || p[2] > 0.01)
121	        .count();
