125	    // total saturation bug or an early-out failure).
126	    let saturated_pixels = frame
127	        .framebuffer
128	        .chunks_exact(3)
129	        .filter(|p| p[0] > 0.99 && p[1] > 0.99 && p[2] > 0.99)
130	        .count();
131	    assert!(
132	        saturated_pixels < 256 * 256 / 2,
