#[repr(C, align(16))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct TileInstance {
    /// Linear tile index: `tile_y * tile_cols + tile_x`.
    pub tile_id: u32,
    /// Index of the gaussian within [`ProjectedBatch`].
