pub struct TileBinning {
    /// Number of tiles along the image X axis (ceil-div of width by [`TILE_SIZE`]).
    pub tile_cols: u32,
    /// Number of tiles along the image Y axis (ceil-div of height by [`TILE_SIZE`]).
    pub tile_rows: u32,
